# Try: mark cells based on their local 5-neighbor count
import numpy as np

grid = np.array([list(map(int, line.split())) for line in grid_str.strip().split('\n')])

# For each 5, count how many 5-neighbors it has in the 8-neighborhood
output_from_5_neighbors = np.zeros_like(grid)
for r in range(30):
    for c in range(17):
        if grid[r, c] == 5:
            # Check 8 neighbors
            neighbor_count = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 30 and 0 <= nc < 17:
                        if grid[nr, nc] == 5:
                            neighbor_count += 1

            # If has exactly 2 neighbors, mark as 1
            if neighbor_count == 2:
                output_from_5_neighbors[r, c] = 1

print("Cells with exactly 2 5-neighbors:")
print(f"Total: {np.sum(output_from_5_neighbors)}")
print("Sample (first 10 rows, columns 8-15):")
print(output_from_5_neighbors[:10, 8:15])

# Check if the original 1s position has a 5 with 2 neighbors nearby
print("\nNeighbors of positions around original 1s (at column 10):")
for r in range(1, 8):
    print(f"Row {r}: {output_from_5_neighbors[r, :]}")

